/* ---------- Room hero: Table Mountain view pulls back into a living room ---------- */
let zq=0;function sizeCv(){}
const RM={iw:1832,ih:858,win:[28,45,1080,520]};
const ez=t=>t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2,lp=(a,b,t)=>a+(b-a)*t,cl=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));
let rmInit=false;
window.flyLoop=function flyLoop(){if(current==='home'){const fl=$('#fly'),vh=innerHeight;const r=fl.getBoundingClientRect();const p=cl(-r.top/(fl.offsetHeight-vh));
  zq+=(p-zq)*(reduce?1:.12);const q=zq;const mob=innerWidth<=860;
  const st=fl.querySelector('.fly-st'),W=st.offsetWidth,H=st.offsetHeight;
  const k=Math.max(W/RM.iw,H/RM.ih),w=RM.iw*k,h=RM.ih*k;
  const room=$('#room'),rw=$('#rwin');
  room.style.width=w+'px';room.style.height=h+'px';
  const [x1,y1,x2,y2]=RM.win;const wx=x1*k,wy=y1*k,ww=(x2-x1)*k,wh=(y2-y1)*k;
  rw.style.left=wx+'px';rw.style.top=wy+'px';rw.style.width=ww+'px';rw.style.height=wh+'px';
  const fx=mob?.33:.5;const baseX=Math.min(0,Math.max(W-w,W*fx-w*fx*1.0-(mob?(w*.0):0)));const bx=mob?Math.min(0,Math.max(W-w,W/2-.3*w)):(W-w)/2,by=(H-h)/2;
  const S0=Math.max(W/ww,H/wh)*1.02;
  const c={x:wx+ww/2,y:wy+wh/2};
  const t=ez(cl(q/.85));
  const s1=lp(S0,1,t);const Px=lp(W/2,bx+c.x,t),Py=lp(H/2,by+c.y,t);
  room.style.transform=`translate3d(${(Px-c.x*s1).toFixed(1)}px,${(Py-c.y*s1).toFixed(1)}px,0) scale(${s1.toFixed(4)})`;
  rw.style.opacity=(1-cl((t-.45)/.35)).toFixed(3);
  {const Tx=Px-c.x*s1,AR=1832/858;const vl=Math.max(0,-Tx/s1-wx),vr=Math.min(ww,(W-Tx)/s1-wx),visW=Math.max(1,vr-vl);
   const iw2=mob?ww:Math.min(ww,visW+2),il=mob?0:vl+(visW-iw2)/2,ih2=iw2/AR;const im=rw.firstChild;
   im.style.width=iw2+'px';im.style.height=ih2+'px';im.style.left=il+'px';im.style.top=(wh-ih2)+'px'}
  const o1=Math.max(0,1-q/.28),o2=cl((q-.42)/.25);
  const p1=$('#ph1'),p2=$('#ph2');p1.style.opacity=o1;p1.style.transform=mob?`translateY(${(-q*80).toFixed(1)}px)`:`translateY(calc(-50% - ${(q*120).toFixed(1)}px))`;p1.style.visibility=o1<.02?'hidden':'visible';
  p2.style.opacity=o2;p2.style.transform=mob?`translateY(${((1-o2)*40).toFixed(1)}px)`:`translateY(calc(-50% + ${((1-o2)*50).toFixed(1)}px))`;p2.style.visibility=o2<.02?'hidden':'visible';
  $('#flyDim').style.opacity=cl((q-.35)/.3).toFixed(3);
  $$('#s4>div').forEach((d,k2)=>{const o=cl((q-.5-k2*.07)/.14);d.style.opacity=o;d.style.transform=`translateY(${((1-o)*24).toFixed(1)}px)`});
  const lbl=t<.5?'V&A Waterfront':'Your home in Cape Town';if($('#flyHere').textContent!==lbl)$('#flyHere').textContent=lbl;
 }requestAnimationFrame(flyLoop)};
