const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('pre');io.unobserve(e.target)}}),{threshold:.15});
function armReveal(){{const ab=$('.view.active .ab2');if(ab&&!reduce&&!ab.classList.contains('in')){if(ab.getBoundingClientRect().top>innerHeight*.9){ab.classList.add('pre');const o=new IntersectionObserver(es=>{if(es[0].isIntersecting){ab.classList.remove('pre');ab.classList.add('in');o.disconnect()}},{threshold:.2});o.observe(ab)}else ab.classList.add('in')}else if(ab)ab.classList.add('in')}$$('.view.active .rv').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight*.95){el.classList.add('pre');io.observe(el)}})}
