function sizeMini(){const l=$('#ctL1'),m=$('[data-mini]');if(!l||!m||!l.offsetWidth)return;const r=document.createRange();r.selectNodeContents(l);const w=r.getBoundingClientRect().width;m.style.maxWidth=innerWidth>560?Math.ceil(w)+'px':'';const f=$('#form'),th=$('#thanks');[f,th,$('#ctSel')].forEach(e=>{if(e)e.style.maxWidth=innerWidth>560?Math.ceil(w)+'px':''})}
